import {renderArmyDeployment,readDeploymentMoves} from './army-deployment-ui.js';
import {preparationControls} from './market-actions-ui.js';
import {AREAS} from './world.js';
import {militaryDestinations} from './military.js';
export function renderMilitaryForm(s,id,card={},cards={}){const gain=card.armyGain??1,maxMoves=card.maxMoves??2,destinations=[...new Set([...militaryDestinations(s),...(card.destinationOverride?[card.destinationOverride]:[])])];
 const shown=card.onlyDestination?[card.onlyDestination]:s.config.wit?Object.keys(AREAS):destinations;
 return `<section id="basic-form" data-card-id="${id}" class="flow-panel"><b>${card.name||'军事增援'} · 自动结算</b>${preparationControls(s,card,cards)}<p>${gain?'先获得'+gain+'军队。':''}依次移动${card.minMoves?card.minMoves+'～':''}${maxMoves}次，每次支付${card.moveCost??5}资金。</p>${renderArmyDeployment(s,{gain,maxMoves,destinations:shown,normalDestinations:destinations,production:card.produceArmies?'#market-army-production':''})}${card.resetAfterMoves?`<label>移动后可重置一个临时影响力<select id="market-reset"><option value="">不重置</option>${Object.entries(s.regions).flatMap(([region,r])=>r.temporary.map((owner,index)=>owner===s.current?`<option value="${region}:${index}">${AREAS[region].name} · 第${index+1}个临时位置</option>`:'')).join('')}</select></label><p>只能选择本次有军队移入的地区。</p>`:''}<p id="basic-preview" aria-live="polite"></p><button id="commit-basic" data-card-action="playBasicCard" data-id="${id}">结算并完成本次行动</button><p class="minor">SP按每次移动分别支付；其他特殊卡牌修正仍需手动处理。</p></section>`;
}
export function readMilitaryMoves(){const plan=document.querySelector('.army-deployment');if(plan)return readDeploymentMoves(plan);return [...document.querySelectorAll('[data-military-to]')].filter(el=>el.value).map(el=>({from:document.querySelector(`[data-military-from="${el.dataset.militaryTo}"]`).value,to:el.value,spendSP:!!document.querySelector(`[data-military-sp="${el.dataset.militaryTo}"]`)?.checked}));}
export function militarySummary(preview){return `获得${preview.armyGain??1}军队，移动${preview.moves.length}次，支付${preview.cost}资金；结算后待命军队${preview.reserve}。`+preview.moves.map(m=>`${m.from==='reserve'?'待命区':AREAS[m.from].name} → ${AREAS[m.to].name}`).join('；');}
